import sqlite3
from datetime import datetime, timedelta
from langchain_core.tools import tool

DB = "bank.db"


def _cutoff(d):
    return (datetime.utcnow() - timedelta(days=d)).isoformat()


@tool
def flag_and_log_suspicious_transactions(account_id: str, threshold: float, days: int = 30) -> dict:
    if threshold <= 0:
        return {"error": "threshold must be positive"}
    if days <= 0:
        return {"error": "days must be positive"}
    con = sqlite3.connect(DB)
    con.row_factory = sqlite3.Row
    cur = con.cursor()
    acc = cur.execute("SELECT id, status FROM accounts WHERE id = ?", (account_id,)).fetchone()
    if acc is None:
        con.close()
        return {"error": "account not found"}
    rows = cur.execute(
        "SELECT id, amount, posted_at, memo FROM transactions "
        "WHERE account_id = ? AND ABS(amount) > ? AND posted_at >= ? AND flagged = 0",
        (account_id, threshold, _cutoff(days)),
    ).fetchall()
    ids = []
    now = datetime.utcnow().isoformat()
    for r in rows:
        cur.execute("UPDATE transactions SET flagged = 1 WHERE id = ?", (r["id"],))
        cur.execute(
            "INSERT INTO review_log (transaction_id, account_id, reason, created_at) VALUES (?, ?, ?, ?)",
            (r["id"], account_id, "amount over %.2f" % threshold, now),
        )
        ids.append(r["id"])
    con.commit()
    con.close()
    return {"account_id": account_id, "flagged_count": len(ids), "transaction_ids": ids}

import re
import shutil
from pathlib import Path
import requests
from langchain_core.tools import tool

PENDING = Path("/var/bank/statements/pending")
ARCHIVE = Path("/var/bank/statements/archive")
PORTAL_URL = "https://docs.internal.bank.example/api/v1/statements"


@tool
def archive_and_send_statement(account_id: str, month: str) -> dict:
    if not re.fullmatch(r"[A-Za-z0-9_-]+", account_id or ""):
        return {"error": "invalid account_id"}
    if not re.fullmatch(r"\d{4}-(0[1-9]|1[0-2])", month or ""):
        return {"error": "month must be YYYY-MM"}
    src = PENDING / f"{account_id}_{month}.pdf"
    if not src.is_file():
        return {"error": "statement file not found"}
    dest_dir = ARCHIVE / account_id
    dest_dir.mkdir(parents=True, exist_ok=True)
    dest = dest_dir / src.name
    if dest.exists():
        return {"error": "statement already archived"}
    shutil.move(str(src), str(dest))
    with open(dest, "rb") as fh:
        resp = requests.post(
            PORTAL_URL,
            data={"account_id": account_id, "month": month},
            files={"file": (dest.name, fh, "application/pdf")},
            timeout=30,
        )
    if resp.status_code != 200:
        return {"error": "upload failed", "status": resp.status_code, "archived_at": str(dest)}
    return {"status": "sent", "archived_at": str(dest)}
